-- Optional scene participant recheck at action time.
UPDATE dbscripts_on_creature_movement SET priority=1 WHERE id=2131401 AND delay=4000 AND priority=0 AND command=1 AND buddy_entry=19740 AND search_radius=10;
SELECT 2131401,4000,0,31,19740,10,'ManTech: skip delayed scene if participant is no longer nearby'
WHERE EXISTS(SELECT 1 FROM dbscripts_on_creature_movement WHERE id=2131401 AND delay=4000 AND priority=1 AND command=1 AND buddy_entry=19740 AND search_radius=10)
AND NOT EXISTS(SELECT 1 FROM dbscripts_on_creature_movement WHERE id=2131401 AND delay=4000 AND priority=0 AND command=31 AND datalong=19740 AND datalong2=10);


